// Hand-written. Not generated by Speakeasy.
//
// Refuses a client configuration naming more than one certificate subject type.
//
// Authlete accepts exactly one and rejects two with A032216, an error that does
// not say which attributes conflict. Catching it at plan time means nothing is
// sent, nothing changes, and the message names both.
//
// This is the counterpart to the plan modifier in
// internal/provider/planmodifiers: the modifier resolves the unambiguous case,
// where configuration names one subject type and a stale value survives in
// state. Two named at once is the practitioner's ambiguity, and guessing which
// they meant would configure authentication differently from what their
// configuration says. So that case stops here instead.
//
// ConfigValidators is declared on ClientResource from this file rather than the
// generated client_resource.go: Go allows a type's methods to live in any file
// of the package, so this adds behaviour without editing generated code.
package provider

import (
	"context"
	"fmt"
	"strings"

	"github.com/authlete/terraform-provider-authlete/internal/provider/planmodifiers"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

var _ resource.ResourceWithConfigValidators = (*ClientResource)(nil)

func (r *ClientResource) ConfigValidators(_ context.Context) []resource.ConfigValidator {
	return []resource.ConfigValidator{singleCertificateSubjectType{}}
}

type singleCertificateSubjectType struct{}

func (singleCertificateSubjectType) Description(_ context.Context) string {
	return "at most one certificate subject type may be set"
}

func (v singleCertificateSubjectType) MarkdownDescription(ctx context.Context) string {
	return v.Description(ctx)
}

func (singleCertificateSubjectType) ValidateResource(ctx context.Context, req resource.ValidateConfigRequest, resp *resource.ValidateConfigResponse) {
	var set []string
	for _, attr := range planmodifiers.MTLSSubjectAttributes {
		var v types.String
		if diags := req.Config.GetAttribute(ctx, path.Root(attr), &v); diags.HasError() {
			// The attribute is absent from the schema; nothing to check.
			continue
		}
		if !v.IsNull() && !v.IsUnknown() && v.ValueString() != "" {
			set = append(set, attr)
		}
	}
	if len(set) < 2 {
		return
	}

	resp.Diagnostics.AddAttributeError(
		path.Root(set[0]),
		"Only one certificate subject type may be set",
		fmt.Sprintf(
			"%s are all set. Authlete accepts exactly one way of identifying a client's "+
				"certificate and rejects a request naming more than one (A032216).\n\n"+
				"Remove whichever no longer applies. Deleting the line is enough: the "+
				"provider clears the previous value and shows the change in the plan. "+
				"Setting it to an empty string does not work, because an empty string "+
				"still counts as naming that subject type.",
			strings.Join(set, " and ")),
	)
}
